mapper.select:
SELECT MSG_MST_NO AS MSGID
FROM ${main_table}
WHERE ROWID IN (
    SELECT /*+ INDEX(MSA_MSG_SNDNG_B MSA_MSG_SNDNG_B_IDX3) */ ROWID
    FROM ${main_table}
    WHERE SNDNG_TYPE_CD IN (${flag_msg_type})
    AND MSG_STTS_CD = '00'
    AND GDBK_TRSM_MTHD_CD = '02'
    AND (SNDNG_PRNMNT_YMD < TO_CHAR(SYSDATE, 'YYYYMMDD')
        OR (SNDNG_PRNMNT_YMD = TO_CHAR(SYSDATE, 'YYYYMMDD') AND GDBK_SNDNG_PRNMNT_TM <= TO_CHAR(SYSDATE, 'HH24MISS'))
        ) ORDER BY MOBL_REG_TYPE_CD , SNDNG_PRNMNT_YMD, GDBK_SNDNG_PRNMNT_TM
    FETCH FIRST 500 ROWS ONLY
) ORDER BY MOBL_REG_TYPE_CD , SNDNG_PRNMNT_YMD, GDBK_SNDNG_PRNMNT_TM, REG_DT

SELECT MSG_MST_NO AS MSGID
FROM ${main_table}
WHERE ROWID IN (
    SELECT /*+ INDEX(MSA_MSG_SNDNG_B MSA_MSG_SNDNG_B_IDX3) */ ROWID
    FROM ${main_table}
    WHERE SNDNG_TYPE_CD IN (${flag_msg_type})
      AND MSG_STTS_CD = '00'
      AND GDBK_TRSM_MTHD_CD = '01'
      AND (SNDNG_PRNMNT_YMD < TO_CHAR(SYSDATE, 'YYYYMMDD')
        OR (SNDNG_PRNMNT_YMD = TO_CHAR(SYSDATE, 'YYYYMMDD') AND GDBK_SNDNG_PRNMNT_TM <= TO_CHAR(SYSDATE, 'HH24MISS'))
        ) ORDER BY MOBL_REG_TYPE_CD , SNDNG_PRNMNT_YMD, GDBK_SNDNG_PRNMNT_TM
      FETCH FIRST 500 ROWS ONLY
) ORDER BY MOBL_REG_TYPE_CD , SNDNG_PRNMNT_YMD, GDBK_SNDNG_PRNMNT_TM, REG_DT

mapper.update:
UPDATE ${main_table}
SET MSG_STTS_CD = '01',
    ISND_PRCS_DT = SYSTIMESTAMP,
    MDFCN_DT = SYSTIMESTAMP,
    MDFR_ID = #{mod_id}
WHERE MSG_MST_NO IN (${strmsgid})
